\label{lem:maxchar}
Let $P\subsetneq I$ be a packing for $c$.  Then $P$ is maximal if and only
if $c-w(P)<\min_{j\in I\setminus P}w_j$; with integral weights,
$c-\min_{j\in I\setminus P}w_j+1\le w(P)\le c$.

\label{thm:noconst}
Unless $\mathsf{P}=\mathsf{NP}$:
\begin{enumerate}[label=(\alph*),leftmargin=2em]
  \par\hangindent 40\p@ \textcolor{black}{neither \textnormal{MinMax-Pack}\xspace nor \textnormal{MaxMin-Cov}\xspace admits a polynomial-time
        $\alpha$-approximation, for any $\alpha\ge1$;}
  \par\hangindent 40\p@ if all values are required to be positive, neither \textnormal{MinMax-Pack}\xspace nor
        \textnormal{MaxMin-Cov}\xspace admits a polynomial-time $2^{p(n)}$-approximation, for any
        polynomial $p$.
\end{enumerate}

\label{thm:unitgap}
For every fixed $0<\varepsilon<1$, unless $\mathsf{P}=\mathsf{NP}$:
\begin{enumerate}[label=(\alph*),leftmargin=2em]
  \par\hangindent 40\p@ unit-cost \textnormal{MinMax-Pack}\xspace admits no polynomial-time
        $n^{1-\varepsilon}$-approximation;
  \par\hangindent 40\p@ unit-profit \textnormal{MaxMin-Cov}\xspace admits no polynomial-time
        $n^{1-\varepsilon}$-approximation.
\end{enumerate}

\label{thm:spread}
Let $\kappa$ be the spread defined in \eqref{eq:kappa}.
For every $\varepsilon>0$:
\begin{enumerate}[label=(\alph*),leftmargin=2em]
  \par\hangindent 40\p@ \textnormal{MinMax-Pack}\xspace admits a $(1+\varepsilon)\kappa$-approximation;
  \par\hangindent 40\p@ \textnormal{MaxMin-Cov}\xspace admits a $(1+\varepsilon)\kappa$-approximation;
\end{enumerate}
in both cases with running time polynomial in the input size and $1/\varepsilon$.

\label{rem:linearspread}
Any approximation for the proportional problem can be used instead, at the
price of its factor: Max Greedy gives a linear-time $2\kappa$-approximation
on the cover side and the $4/3$-approximation of Theorem~\ref{thm:gmp-lbp}
gives $\frac43\kappa$ on the packing side.
